SELECT facility_name, overall_rating
FROM hq.hospitals
WHERE UPPER(facility_name) = UPPER('O''Brien''; DROP TABLE hq.hospitals; --');

SELECT COUNT(*) AS texas_hospital_count
FROM hq.hospitals
WHERE UPPER(state) = 'TX';

SELECT facility_name, overall_rating
FROM hq.hospitals
WHERE UPPER(facility_name) = UPPER($$x' UNION SELECT rolname, rolpassword FROM pg_authid --$$);

SELECT COUNT(*) AS texas_hospital_count
FROM hq.hospitals
WHERE UPPER(state) = UPPER('TX');

SELECT COUNT(DISTINCT facility_id) AS hospitales_en_texas
FROM hq.hospitals
WHERE UPPER(state) = 'TX';

SELECT COUNT(*) AS texas_hospital_count
FROM hq.hospitals
WHERE is_texas = TRUE;

SELECT COUNT(*) AS texas_hospitals_with_5_stars
FROM hq.v_scorecard
WHERE overall_rating = 5;
